#include <stdio.h>
#include <stdlib.h>

struct Produtos {
    int codigo_produto;
    int qtd_estoque;
    int qtd_minima;
    int qtd_vendida;
    int necessidade_transferencia;
    int qtd_transferencia;
};

struct Vendas {
    int situacao_venda;
    int codigo_produto;
    int quantidade_vendida;
    int canal_venda;
};

int main() {
    int i, j;
    int tam_produtos = 0;
    int tam_vendas = 0;
    struct Produtos *produtos = NULL;
    struct Vendas *vendas = NULL;
    FILE *arquivo_produtos, *arquivo_vendas, *arquivo_saida, *arquivo_divergencias;

    // Lê o arquivo de produtos
    arquivo_produtos = fopen("produtos.txt", "r");
    if (arquivo_produtos == NULL) {
        printf("O arquivo produtos nao foi encontrado.");
        return 1;
    }
    while (fscanf(arquivo_produtos, "%d;%d;%d\n", &produtos[tam_produtos].codigo_produto, &produtos[tam_produtos].qtd_estoque, &produtos[tam_produtos].qtd_minima) != EOF) {
        tam_produtos++;
        produtos = (struct Produtos *)realloc(produtos, sizeof(struct Produtos) * (tam_produtos + 1));
    }
    fclose(arquivo_produtos);

    // Lê o arquivo de vendas
    arquivo_vendas = fopen("vendas.txt", "r");
    if (arquivo_vendas == NULL) {
        printf("O arquivo vendas nao foi encontrado.");
        return 1;
    }
    while (fscanf(arquivo_vendas, "%d;%d;%d;%d\n", &vendas[tam_vendas].codigo_produto, &vendas[tam_vendas].quantidade_vendida, &vendas[tam_vendas].situacao_venda, &vendas[tam_vendas].canal_venda) != EOF) {
        tam_vendas++;
        vendas = (struct Vendas *)realloc(vendas, sizeof(struct Vendas) * (tam_vendas + 1));
    }
    fclose(arquivo_vendas);

    // Processa as informações
    for (i = 0; i < tam_produtos; i++) {
        produtos[i].qtd_vendida = 0;
        for (j = 0; j < tam_vendas; j++) {
            if (vendas[j].codigo_produto == produtos[i].codigo_produto) {
                produtos[i].qtd_vendida += vendas[j].quantidade_vendida;
            }
        }
        produtos[i].necessidade_transferencia = produtos[i].qtd_minima - produtos[i].qtd_estoque;
        if (produtos[i].necessidade_transferencia < 0) {
            produtos[i].necessidade_transferencia = 0;
        }
        produtos[i].qtd_transferencia = produtos[i].qtd_vendida - produtos[i].necessidade_transferencia;
        if (produtos[i].qtd_transferencia < 0) {
            produtos[i].qtd_transferencia = 0;
        }
    }

    // Escreve o arquivo de saída
    arquivo_saida = fopen("TRANSFERE.txt", "w");
    if (arquivo_saida == NULL) {
        printf("Erro ao criar arquivo de saida.");
        return 1;
    }
    for (i = 0; i < tam_produtos; i++) {
        fprintf(arquivo_saida, "%05d;%03d;%03d;%03d;%03d;%03d;\n", produtos[i].codigo_produto, produtos[i].qtd_estoque, produtos[i].qtd_minima, produtos[i].qtd_vendida, produtos[i].necessidade_transferencia, produtos[i].qtd_transferencia);
    }
    fclose(arquivo_saida);

    // Escreve o arquivo de divergências
    arquivo_divergencias = fopen("divergencias.txt", "w");
    if (arquivo_divergencias == NULL) {
        printf("Erro ao criar arquivo de divergencias.");
        return 1;
    }
    for (i = 0; i < tam_vendas; i++) {
        for (j = 0; j < tam_produtos; j++) {
            if (vendas[i].codigo_produto == produtos[j].codigo_produto) {
                if (vendas[i].quantidade_vendida > produtos[j].qtd_estoque) {
                    fprintf(arquivo_divergencias, "Produto %05d: venda de %03d unidades com estoque insuficiente (%03d unidades)\n", vendas[i].codigo_produto, vendas[i].quantidade_vendida, produtos[j].qtd_estoque);
                }
                if (vendas[i].situacao_venda == 1 && vendas[i].quantidade_vendida > 10) {
                    fprintf(arquivo_divergencias, "Produto %05d: venda de %03d unidades com situacao de venda invalida (%d)\n", vendas[i].codigo_produto, vendas[i].quantidade_vendida, vendas[i].situacao_venda);
                }
            }
        }
    }
    fclose(arquivo_divergencias);

    return 0;
}
